_FREL_NOMS = {s: n for s, n, *_ in _FV}

def _titre_frel(nom, dep):
    for t in ("Destruction Nid de Frelons %s (%s) | Proxinuisibles" % (nom, dep),
              "Nid de Frelons et Guêpes %s (%s) | Proxinuisibles" % (nom, dep),
              "Nid de Frelons %s (%s) | Proxinuisibles" % (nom, dep),
              "Nid de Frelons %s | Proxinuisibles" % nom,
              "Nid de Frelons et Guêpes %s" % nom):
        if len(t) <= 60:
            return t
    return "Nid de Frelons %s" % nom

def _meta_frel(nom, dep):
    for m in ("Destruction de nids de frelons et de guêpes à %s (%s) : intervention rapide, matériel de protection, devis gratuit et déplacement compris." % (nom, dep),
              "Destruction de nids de frelons et de guêpes à %s (%s) : intervention rapide, devis gratuit, déplacement compris." % (nom, dep),
              "Nids de frelons et de guêpes à %s (%s) : intervention rapide et devis gratuit." % (nom, dep)):
        if len(m) <= 155:
            return m
    return "Destruction de nids de frelons et de guêpes à %s." % nom

for _i, (slug, nom, dep, lead, local) in enumerate(_FV):
    path = "/frelons-guepes-%s/" % slug
    if path in P:
        continue
    _tri = _COMBOS[_i % len(_COMBOS)]
    secs = [local] + [_POOL[j] for j in _tri]
    secs.append(("Mon intervention à %s" % nom, _FIN[_i % len(_FIN)] % {"nom": nom}))
    _ftri = _FCOMBOS[_i % len(_FCOMBOS)]
    faq = [_FAQ_POOL[j] for j in _ftri]
    liens_svc = [("Frelon asiatique", "/frelon-asiatique/"), ("Tout sur les frelons et guêpes", "/frelons-guepes/")]
    if ("/deratisation-%s/" % slug) in P:
        liens_svc.insert(0, ("Dératisation à %s" % nom, "/deratisation-%s/" % slug))
    if ("/punaises-de-lit-%s/" % slug) in P:
        liens_svc.append(("Punaises de lit à %s" % nom, "/punaises-de-lit-%s/" % slug))
    liens_svc += [("Chenilles processionnaires", "/chenilles-processionnaires/"), ("Piégeur agréé", "/piegeur-agree/")]
    voisins = [(n, "/frelons-guepes-%s/" % s) for s, n, *_ in _FV[max(0, _i - 2):_i] + _FV[_i + 1:_i + 3]]
    links = [("Autres services à %s" % nom, liens_svc)]
    if voisins:
        links.append(("Communes voisines", [("Nid de frelons à %s" % n, u) for n, u in voisins]))
    links.append(("Voir aussi", [("Zones d'intervention", "/zones-intervention/"), ("Particuliers", "/particuliers/"),
                                 ("Professionnels", "/professionnels/"), ("Devis et contact", "/contact/")]))
    add(path, h1="Destruction de nid de frelons et de guêpes à %s (%s)" % (nom, dep),
        title=_titre_frel(nom, dep), meta=_meta_frel(nom, dep),
        lead=lead, secs=secs, faq=faq, links=links, kind="ville")

